628     GLM_FUNC_QUALIFIER uint32 packF3x9_E1x5(vec3 const& v)
629     {
630         float const SharedExpMax = (pow(2.0f, 9.0f - 1.0f) / pow(2.0f, 9.0f)) * pow(2.0f, 31.f - 15.f);
631         vec3 const Color = clamp(v, 0.0f, SharedExpMax);
632         float const MaxColor = max(Color.x, max(Color.y, Color.z));
633 
634         float const ExpSharedP = max(-15.f - 1.f, floor(log2(MaxColor))) + 1.0f + 15.f;
635         float const MaxShared = floor(MaxColor / pow(2.0f, (ExpSharedP - 15.f - 9.f)) + 0.5f);
636         float const ExpShared = equal(MaxShared, pow(2.0f, 9.0f), epsilon<float>()) ? ExpSharedP + 1.0f : ExpSharedP;
637 
638         uvec3 const ColorComp(floor(Color / pow(2.f, (ExpShared - 15.f - 9.f)) + 0.5f));
639 
640         detail::u9u9u9e5 Unpack;
641         Unpack.data.x = ColorComp.x;
642         Unpack.data.y = ColorComp.y;
643         Unpack.data.z = ColorComp.z;
644         Unpack.data.w = uint(ExpShared);
645         return Unpack.pack;
646     }
647 
648     GLM_FUNC_QUALIFIER vec3 unpackF3x9_E1x5(uint32 v)
649     {
650         detail::u9u9u9e5 Unpack;
651         Unpack.pack = v;
652 
653         return vec3(Unpack.data.x, Unpack.data.y, Unpack.data.z) * pow(2.0f, static_cast<float>(Unpack.data.w) - 15.f - 9.f);
654     }
