656     // Based on Brian Karis http://graphicrants.blogspot.fr/2009/04/rgbm-color-encoding.html
657     template<typename T, qualifier Q>
658     GLM_FUNC_QUALIFIER vec<4, T, Q> packRGBM(vec<3, T, Q> const& rgb)
659     {
660         vec<3, T, Q> const Color(rgb * static_cast<T>(1.0 / 6.0));
661         T Alpha = clamp(max(max(Color.x, Color.y), max(Color.z, static_cast<T>(1e-6))), static_cast<T>(0), static_cast<T>(1));
662         Alpha = ceil(Alpha * static_cast<T>(255.0)) / static_cast<T>(255.0);
663         return vec<4, T, Q>(Color / Alpha, Alpha);
664     }
665 
666     template<typename T, qualifier Q>
667     GLM_FUNC_QUALIFIER vec<3, T, Q> unpackRGBM(vec<4, T, Q> const& rgbm)
668     {
669         return vec<3, T, Q>(rgbm.x, rgbm.y, rgbm.z) * rgbm.w * static_cast<T>(6);
670     }
